mapper.select:
select distinct rac.PROD_ID prodId, rac.PUB_DATE pubDate, rpi.PROD_NAME prodName, rac.ASSETS_CODE assetCode, rac.ASSETS_NAME assetName, rac.FAIR_VALUE fairValue, rac.PD_PROP pdDrop, rac.STATUS status, rac.UPDATE_TIME updateTime, rac.UPDATE_USER updateUser from REP_ASSETS_COMB rac left join V_REP_PROD_INFO rpi on rac.PROD_ID = rpi.PROD_ID
AND rac.PROD_ID in
#{item}
AND rac.ASSETS_CODE =#{assetCode}
AND rac.STATUS=#{status}
AND PUB_DATE >= TO_DATE(#{dateStart},'YYYY-MM-DD')
AND PUB_DATE <= TO_DATE(#{dateEnd},'YYYY-MM-DD')
order by updateTime desc

mapper.delete:
delete from BOK_BALANCE_FSE
where BOOKSET_ID = #{booksetId,jdbcType=VARCHAR} and
DATE_START = #{dateStart,jdbcType=DATE}
and DATE_END = #{dateEnd,jdbcType=DATE}
and SUBJECT_NO = #{subjectNo,jdbcType=VARCHAR}

mapper.select:
select PROD_RE
from V_REP_PROD_INFO
where PROD_RE = #{prodRegistNo,jdbcType=VARCHAR}
